"use client"

import React, { useState } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import Link from 'next/link'
import { Search, Award, School, Globe, User, FileText, Loader2, ExternalLink } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { ElegantBackground } from '@/components/ui/elegant-background'
import { searchCertificate, Certificate } from './actions'

export default function CertificatePortal() {
  const [query, setQuery] = useState('')
  const [results, setResults] = useState<Certificate[]>([])
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const [hasSearched, setHasSearched] = useState(false)
  const [recentSearches, setRecentSearches] = useState<string[]>([])

  React.useEffect(() => {
    const saved = localStorage.getItem('recent_certificate_searches')
    if (saved) {
      setRecentSearches(JSON.parse(saved))
    }
  }, [])

  const addToRecent = (term: string) => {
    const updated = [term, ...recentSearches.filter(s => s !== term)].slice(0, 5)
    setRecentSearches(updated)
    localStorage.setItem('recent_certificate_searches', JSON.stringify(updated))
  }

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!query.trim()) return

    setLoading(true)
    setError('')
    setResults([])
    setHasSearched(true)
    addToRecent(query.trim())

    try {
      const response = await searchCertificate(query.trim())
      if (response.success && response.data) {
        setResults(response.data)
      } else {
        setError(response.error || 'No certificates found')
      }
    } catch {
      setError('An error occurred while searching')
    } finally {
      setLoading(false)
    }
  }

  const clearRecent = () => {
    setRecentSearches([])
    localStorage.removeItem('recent_certificate_searches')
  }

  return (
    <div className="min-h-screen relative overflow-hidden">
      <ElegantBackground variant="section" />
      
      <div className="relative z-10 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-24">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6 }}
          className="text-center mb-12"
        >
          <h1 className="font-[family-name:var(--font-cinzel)] text-4xl md:text-5xl font-bold text-foreground mb-4">
            Certificate <span className="text-accent-gold">Portal</span>
          </h1>
          <p className="text-lg text-muted-foreground max-w-2xl mx-auto">
            Verify and view IGACMUN certificates. Enter your Certificate ID below.
          </p>
        </motion.div>

        {/* Search Section */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6, delay: 0.2 }}
          className="max-w-2xl mx-auto mb-16"
        >
          <form onSubmit={handleSearch} className="relative flex items-center">
            <div className="relative w-full group">
              <div className="absolute inset-0 bg-accent-gold/20 rounded-lg blur-md group-hover:blur-lg transition-all duration-300 opacity-50" />
              <input
                type="text"
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                placeholder="Enter Certificate ID (e.g. 123456)"
                className="w-full bg-forest-900/80 border border-accent-gold/30 text-foreground placeholder:text-muted-foreground/50 rounded-lg py-4 pl-12 pr-32 focus:outline-none focus:border-accent-gold/60 focus:ring-1 focus:ring-accent-gold/60 transition-all backdrop-blur-sm relative z-10"
              />
              <Search className="absolute left-4 top-1/2 transform -translate-y-1/2 text-accent-gold/70 h-5 w-5 z-20" />
              
              <div className="absolute right-2 top-1/2 transform -translate-y-1/2 z-20">
                <Button 
                  type="submit" 
                  disabled={loading}
                  className="bg-accent-gold/10 hover:bg-accent-gold/20 text-accent-gold border border-accent-gold/30"
                >
                  {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : 'Verify'}
                </Button>
              </div>
            </div>
          </form>

          {!hasSearched && recentSearches.length > 0 && (
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              className="mt-4 flex flex-wrap items-center justify-center gap-2"
            >
              <span className="text-xs text-muted-foreground mr-2">Recent:</span>
              {recentSearches.map((term) => (
                <button
                  key={term}
                  onClick={() => {
                    setQuery(term)
                    // Optional: auto-trigger search
                  }}
                  className="text-xs px-3 py-1 rounded-full bg-forest-900/50 border border-accent-gold/20 text-accent-gold/80 hover:bg-accent-gold/10 hover:text-accent-gold transition-colors"
                >
                  {term}
                </button>
              ))}
              <button
                onClick={clearRecent}
                className="text-xs text-muted-foreground hover:text-destructive ml-2 transition-colors"
              >
                Clear
              </button>
            </motion.div>
          )}
        </motion.div>

        {/* Results Section */}
        <div className="max-w-3xl mx-auto">
          <AnimatePresence mode="wait">
            {loading ? (
              <motion.div
                key="loading"
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                className="flex justify-center py-12"
              >
                <div className="flex flex-col items-center gap-4">
                  <div className="relative">
                    <div className="w-12 h-12 border-4 border-accent-gold/20 border-t-accent-gold rounded-full animate-spin" />
                    <div className="absolute inset-0 flex items-center justify-center">
                      <div className="w-2 h-2 bg-accent-gold rounded-full animate-pulse" />
                    </div>
                  </div>
                  <p className="text-accent-gold/70 font-medium animate-pulse">Verifying ID...</p>
                </div>
              </motion.div>
            ) : error ? (
              <motion.div
                key="error"
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0 }}
                className="text-center py-12"
              >
                <div className="bg-destructive/10 border border-destructive/30 rounded-lg p-6 max-w-md mx-auto">
                  <p className="text-destructive font-medium">{error}</p>
                </div>
              </motion.div>
            ) : results.length > 0 ? (
              <motion.div
                key="results"
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                className="flex justify-center"
              >
                {results.slice(0, 1).map((cert, index) => (
                  <motion.div
                    key={cert.id}
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ duration: 0.5, delay: index * 0.1 }}
                    className="group relative w-full max-w-2xl"
                  >
                    <Link href={`/certificate-portal/${cert.certificate_id}`} className="block h-full">
                      <div className="absolute inset-0 bg-gradient-to-br from-accent-gold/10 to-transparent rounded-xl blur-sm opacity-0 group-hover:opacity-100 transition-opacity duration-500" />
                      
                      <div className="relative h-full bg-forest-900/40 border border-accent-gold/20 rounded-xl p-8 backdrop-blur-md hover:border-accent-gold/40 transition-all duration-300 overflow-hidden flex flex-col items-center text-center">
                        {/* Decorative background elements */}
                        <div className="absolute top-0 right-0 w-32 h-32 bg-accent-gold/5 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2" />
                        
                        <div className="relative z-10 w-full">
                          <div className="flex flex-col items-center mb-6">
                            <div className="p-4 bg-accent-gold/10 rounded-full border border-accent-gold/20 mb-4">
                              <Award className="h-10 w-10 text-accent-gold" />
                            </div>
                            <p className="text-xs text-muted-foreground uppercase tracking-wider mb-1">Certificate Found</p>
                            <p className="font-mono text-lg text-accent-gold font-bold">{cert.certificate_id}</p>
                          </div>

                          <div className="space-y-6">
                            <div>
                              <h3 className="font-[family-name:var(--font-cinzel)] text-3xl font-bold text-white mb-2">{cert.participant_name}</h3>
                              <div className="flex items-center justify-center gap-2 text-muted-foreground">
                                <School className="h-4 w-4" />
                                <span className="text-sm">{cert.school}</span>
                              </div>
                            </div>

                            <div className="h-px w-full bg-gradient-to-r from-transparent via-accent-gold/30 to-transparent" />

                            <div className="grid grid-cols-2 gap-6 text-left">
                              <div className="bg-forest-950/30 p-4 rounded-lg border border-accent-gold/10">
                                <p className="text-xs text-muted-foreground mb-1 flex items-center gap-1">
                                  <FileText className="h-3 w-3" /> Type
                                </p>
                                <p className="text-sm font-medium text-foreground">{cert.certificate_type}</p>
                              </div>
                              <div className="bg-forest-950/30 p-4 rounded-lg border border-accent-gold/10">
                                <p className="text-xs text-muted-foreground mb-1 flex items-center gap-1">
                                  <User className="h-3 w-3" /> Committee
                                </p>
                                <p className="text-sm font-medium text-foreground">{(cert as any).committee || 'N/A'}</p>
                              </div>
                            </div>
                          </div>

                          <div className="mt-8 pt-4 border-t border-white/5 flex justify-center">
                            <Button className="bg-accent-gold hover:bg-accent-gold/90 text-forest-950 font-semibold px-8">
                              View Full Certificate <ExternalLink className="ml-2 h-4 w-4" />
                            </Button>
                          </div>
                        </div>
                      </div>
                    </Link>
                  </motion.div>
                ))}
              </motion.div>
            ) : hasSearched ? (
              <motion.div
                key="empty"
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                className="text-center py-12"
              >
                <p className="text-muted-foreground">No certificates found matching your query.</p>
              </motion.div>
            ) : null}
          </AnimatePresence>
        </div>
      </div>
    </div>
  )
}
